globalThis.BF_CONTENT = {"curriculum":{"project":"Black Thought","version":"V1 revised after independent audit","status":"curriculum structure locked for encounter design","learning_goals":["UNDERSTAND","CONNECT","CONTEXTUALIZE","SHARE","APPLY"],"worlds":{"FREEDOM":"What does freedom actually require?","POWER":"Who gets to decide, and how is power exercised?","EDUCATION":"What is learning for?","ECONOMICS":"Who controls work, wealth, and resources?","IDENTITY":"Who defines Blackness and the self?","ORGANIZING":"How do people act together?","CULTURE":"What can art, faith, media, and language do?"},"rules":["Thinkers and ideas drive play; history mostly provides context.","No source-author trivia.","Debates must present both sides fairly and never score a political winner.","Typing stays minimal; active recall can use think-before-reveal.","LENS is optional and replaces the old mandatory modern_bridge field.","TODAY examples are added only when concrete, sourced, neutral, and useful.","Share lines should usually be 15 words or fewer.","Connections used in gameplay should resolve to playable nodes, context cards, debates, or threads."],"playable_nodes":[{"id":"V1-001","subject":"Africa before enslavement","kind":"historical_idea","world":"IDENTITY","era":"pre-1619","core_idea":"Black American history sits inside a longer African history; enslavement is a rupture, not the beginning of Black existence.","share":"Black history doesn’t start in 1619. It starts in Africa.","lens":"Ask what changes when a people’s story begins before their oppression.","source":"Four Hundred Souls","source_section":"1624–1629: Africa"},{"id":"V1-002","subject":"Law helped construct race","kind":"historical_idea","world":"POWER","era":"1600s","core_idea":"Colonial law did not merely reflect racial categories; it helped harden them by assigning unequal status, rights, and inheritance.","share":"Racist law didn’t just enforce race. It helped define what race meant.","lens":"Legal categories can shape social categories, not just record them.","source":"Four Hundred Souls + Black AF History","source_section":"1664–1709 chapters; Black AF History 'How White People Were Invented'"},{"id":"V1-003","subject":"Bacon’s Rebellion and divided interests","kind":"historical_idea","world":"ECONOMICS","era":"1670s","core_idea":"Colonial elites had incentives to sharpen racial divisions among laboring people who could otherwise share economic grievances.","share":"Race and class can divide people who share material problems.","lens":"When a coalition breaks, ask what interests or identities are pulling people apart.","source":"Four Hundred Souls","source_section":"1674–1679: Bacon’s Rebellion"},{"id":"V1-004","subject":"Marronage and autonomous communities","kind":"movement_idea","world":"FREEDOM","era":"1700s","core_idea":"Some enslaved people pursued freedom by leaving slave society and building alternative communities such as maroon settlements and Fort Mose.","share":"Sometimes freedom meant escaping the system and building somewhere else.","lens":"Leave, reform, or build: different strategies begin with different ideas of what is possible.","source":"Four Hundred Souls","source_section":"1719–1724: Maroons and Marronage; 1734–1739: From Fort Mose to Soul City"},{"id":"V1-005","subject":"The spirituals","kind":"cultural_idea","world":"CULTURE","era":"1700s","core_idea":"Spirituals could carry theology, memory, coded meaning, endurance, and visions of freedom simultaneously.","share":"A song can carry history, faith, and strategy at the same time.","lens":"Culture can do intellectual work even when it does not look like an essay.","source":"Four Hundred Souls","source_section":"1724–1729: The Spirituals"},{"id":"V1-006","subject":"Freedom church","kind":"institution_idea","world":"CULTURE","era":"1700s","core_idea":"Independent Black religious life became a place where faith, collective organization, mutual aid, and claims for freedom could meet.","share":"The Black church became both a sanctuary and an organizing institution.","lens":"Institutions can preserve ideas because people meet there repeatedly, not just because leaders speak there.","source":"Four Hundred Souls","source_section":"David George / freedom church; Savannah and early Black churches"},{"id":"V1-007","subject":"Phillis Wheatley","kind":"thinker","world":"EDUCATION","era":"1760s","core_idea":"Black literary achievement challenged claims of Black intellectual inferiority while exposing the burden of having to prove humanity to a hostile public.","share":"Wheatley had to write poems—and prove Black people could think.","lens":"Marginalized people are often asked to create and justify their right to create at once.","source":"Four Hundred Souls","source_section":"1764–1769: Phillis Wheatley"},{"id":"V1-008","subject":"Liberty’s contradiction","kind":"historical_idea","world":"FREEDOM","era":"1700s","core_idea":"Enlightenment and Revolutionary language about universal liberty coexisted with racial hierarchy and slavery, giving Black people both a contradiction to expose and a language to claim.","share":"America preached universal liberty while deciding who counted as universal.","lens":"Compare a society’s principles with who actually receives the rights those principles promise.","source":"Four Hundred Souls","source_section":"1749–1754: Race and the Enlightenment; 1774–1779: The American Revolution"},{"id":"V1-009","subject":"Denmark Vesey","kind":"thinker_organizer","world":"ORGANIZING","era":"1820s","core_idea":"Black resistance could require secret networks, trust, planning, and a willingness to pursue collective freedom under severe repression.","share":"Rebellion required organization long before it required action.","lens":"Under repression, trust and information control become part of strategy.","source":"Four Hundred Souls","source_section":"1819–1824: Denmark Vesey"},{"id":"V1-010","subject":"Freedom’s Journal","kind":"institution_idea","world":"CULTURE","era":"1820s","core_idea":"Black-controlled media let Black communities speak for themselves rather than depend on white institutions to define Black life.","share":"Owning the platform can be part of owning the story.","lens":"Ask who controls the channel through which a community is described.","source":"Four Hundred Souls","source_section":"1824–1829: Freedom’s Journal"},{"id":"V1-011","subject":"Maria Stewart","kind":"thinker","world":"EDUCATION","era":"1830s","core_idea":"Stewart connected Black advancement to education, public voice, economic ambition, and the political agency of Black women.","share":"Stewart argued that Black freedom could not leave Black women behind.","lens":"When a movement says 'the people,' ask who is actually included in that phrase.","source":"Four Hundred Souls","source_section":"1829–1834: Maria Stewart"},{"id":"V1-012","subject":"National Negro Conventions","kind":"institution_idea","world":"ORGANIZING","era":"1830s","core_idea":"Black political thought developed through institutions where people debated abolition, education, migration, and strategy together.","share":"Movements need places to argue about strategy, not only places to protest.","lens":"Deliberation is movement infrastructure too.","source":"Four Hundred Souls","source_section":"1834–1839: The National Negro Conventions"},{"id":"V1-013","subject":"James McCune Smith","kind":"thinker","world":"EDUCATION","era":"1840s","core_idea":"Black intellectuals used scholarship and professional expertise to challenge racial pseudoscience and supposedly objective claims of inferiority.","share":"McCune Smith fought racist 'science' with evidence and expertise.","lens":"When prejudice dresses itself as fact, ask what the evidence actually shows.","source":"Four Hundred Souls","source_section":"1844–1849: James McCune Smith, M.D."},{"id":"V1-014","subject":"Frederick Douglass","kind":"thinker","world":"FREEDOM","era":"1850s–1860s","core_idea":"Douglass linked literacy, abolition, citizenship, political action, and the destruction of slavery; personal escape was not enough while the system remained.","share":"Douglass escaped slavery, then spent his life attacking the system itself.","lens":"Individual mobility and collective freedom are different measurements.","source":"Four Hundred Souls","source_section":"1859–1864: Frederick Douglass"},{"id":"V1-015","subject":"Reconstruction","kind":"historical_idea","world":"POWER","era":"1865–1877","core_idea":"Emancipation opened a second struggle over citizenship, voting, education, labor, land, and political power.","share":"Ending slavery answered one question. Reconstruction asked what freedom required next.","lens":"After a formal barrier falls, ask who controls institutions and resources afterward.","source":"Four Hundred Souls + Black AF History","source_section":"1869–1874: Reconstruction; Black AF History Reconstruction discussion"},{"id":"V1-016","subject":"Atlanta washerwomen","kind":"movement_idea","world":"ECONOMICS","era":"1870s–1880s","core_idea":"Black washerwomen used labor autonomy, common rates, mutual-aid traditions, and collective organization to increase control over their work.","share":"Black washerwomen turned private labor into collective bargaining power.","lens":"Economic power can begin with workers coordinating rules they previously faced alone.","source":"Four Hundred Souls","source_section":"Atlanta / washerwomen and post-Reconstruction Black neighborhoods"},{"id":"V1-017","subject":"Plessy and the Citizens’ Committee","kind":"historical_idea","world":"POWER","era":"1890s","core_idea":"Plessy v. Ferguson legalized 'separate but equal,' but the case itself grew from organized Black resistance to segregation.","share":"Plessy was a defeat in court—and the product of organized resistance.","lens":"A failed legal challenge can still reveal how a community understood the injustice it faced.","source":"Four Hundred Souls","source_section":"1894–1899: Plessy v. Ferguson"},{"id":"V1-018","subject":"Booker T. Washington","kind":"thinker","world":"EDUCATION","era":"1890s–1900s","core_idea":"Washington emphasized industrial education, economic strength, and pragmatic advancement as a route toward Black progress in a hostile political environment.","share":"Washington’s bet: build skills and wealth while navigating a hostile system.","lens":"A strategy can be judged partly by what risks its author believed were realistic at the time.","source":"Four Hundred Souls + Black AF History","source_section":"1899–1904: Booker T. Washington; Wells section"},{"id":"V1-019","subject":"W.E.B. Du Bois — double consciousness","kind":"thinker_idea","world":"IDENTITY","era":"1900s","core_idea":"Du Bois described the strain of knowing oneself while also seeing oneself through a society that devalues Blackness.","share":"Du Bois named the strain of seeing yourself through hostile eyes.","lens":"Ask how much self-image comes from one’s own values versus other people’s expectations.","source":"Black AF History","source_section":"Introduction / The Souls of Black Folk"},{"id":"V1-020","subject":"W.E.B. Du Bois — Black Reconstruction","kind":"thinker_idea","world":"POWER","era":"1930s interpreting 1860s","core_idea":"Du Bois reframed Reconstruction and emancipation around Black agency, arguing that enslaved people helped destroy slavery by withdrawing labor and joining the freedom struggle.","share":"Du Bois made enslaved people actors in emancipation, not spectators to it.","lens":"Ask who disappears when history is told only through presidents, generals, and laws.","source":"Black AF History","source_section":"Black Reconstruction / 'The General Strike' discussion"},{"id":"V1-021","subject":"Ida B. Wells — evidence against racial mythology","kind":"thinker_idea","world":"POWER","era":"1890s","core_idea":"Wells used investigative reporting and statistics to challenge the claim that lynching was a neutral response to crime.","share":"Wells attacked lynching by attacking the lie used to justify it.","lens":"When violence is justified by a story about its victims, check the evidence behind the story.","source":"Black AF History","source_section":"Ida B. Wells section"},{"id":"V1-022","subject":"Ida B. Wells — leverage and self-protection","kind":"thinker_idea","world":"ORGANIZING","era":"1890s","core_idea":"Wells treated migration, boycotts, public exposure, and self-defense as forms of leverage when authorities would not protect Black communities.","share":"Wells paired truth-telling with economic pressure and self-protection.","lens":"Moral argument and leverage are different tools; movements may use both.","source":"Black AF History","source_section":"Ida B. Wells section; Mob Rule discussion"},{"id":"V1-023","subject":"Mary Church Terrell","kind":"thinker_organizer","world":"EDUCATION","era":"1890s–1950s","core_idea":"Terrell used education, writing, club work, anti-lynching advocacy, women’s rights, and direct challenges to segregation as mutually reinforcing forms of public action.","share":"Terrell turned education and status into tools for public action.","lens":"Private achievement can become civic power when it is converted into institutions and organizing.","source":"Black AF History","source_section":"Mary Church Terrell section"},{"id":"V1-024","subject":"Callie House","kind":"thinker_organizer","world":"ECONOMICS","era":"1890s–1910s","core_idea":"House helped build a mass reparations movement among formerly enslaved people through local chapters, churches, agents, and membership organization.","share":"The reparations movement had mass organizers more than a century ago.","lens":"A demand becomes a movement when ordinary people have a structure for participating in it.","source":"Black AF History","source_section":"Ex-slave pension / Callie House discussion"},{"id":"V1-025","subject":"The Great Migration","kind":"historical_idea","world":"FREEDOM","era":"1910s–1970s","core_idea":"Migration became a strategy for pursuing safety, wages, political possibility, and autonomy, not simply a change of address.","share":"Millions moved because geography itself could shape freedom.","lens":"Leaving can be a political strategy when place determines opportunity and safety.","source":"Four Hundred Souls","source_section":"1914–1919: The Great Migration"},{"id":"V1-026","subject":"Harlem Renaissance","kind":"cultural_idea","world":"CULTURE","era":"1920s","core_idea":"The Harlem Renaissance became an argument about who could define Black life and what Black art owed to politics, audiences, and white patronage.","share":"The Harlem Renaissance was also a debate about who Black art was for.","lens":"Art can seek recognition, protest, autonomy, or several goals at once.","source":"Four Hundred Souls","source_section":"1924–1929: The Harlem Renaissance"},{"id":"V1-027","subject":"Zora Neale Hurston","kind":"thinker_artist","world":"CULTURE","era":"1920s–1930s","core_idea":"Hurston treated Black vernacular, folklore, humor, and ordinary life as worthy subjects without requiring them to function only as protest.","share":"Hurston let Black life be more than an argument about racism.","lens":"Creators from marginalized groups may resist being asked to represent the whole group.","source":"Four Hundred Souls","source_section":"1934–1939: Zora Neale Hurston"},{"id":"V1-028","subject":"James Baldwin","kind":"thinker_artist","world":"IDENTITY","era":"1950s","core_idea":"Baldwin pushed against narrow depictions of Black life and used autobiography, criticism, and global perspective to insist on fuller Black humanity.","share":"Baldwin refused narrow stories about what Black life was allowed to be.","lens":"A stereotype can be challenged not only by rebutting it, but by expanding the range of lives shown.","source":"Four Hundred Souls","source_section":"1954–1959 cultural chapter / Notes of a Native Son discussion"},{"id":"V1-029","subject":"The Black Left","kind":"intellectual_tradition","world":"ECONOMICS","era":"1930s–1940s","core_idea":"Black radicals linked racial hierarchy to labor, capitalism, imperialism, and class instead of treating racism only as prejudice.","share":"The Black Left tied race to who owned, worked, and profited.","lens":"Ask whether an inequality is about attitudes, institutions, economic structure, or several at once.","source":"Four Hundred Souls","source_section":"1944–1949: The Black Left"},{"id":"V1-030","subject":"Mary McLeod Bethune","kind":"thinker_organizer","world":"POWER","era":"1930s–1940s","core_idea":"Bethune combined Black institution-building with access to federal decision-makers to pursue jobs, education, and policy opportunities.","share":"Bethune built institutions outside government and leverage inside it.","lens":"Access and independence can be complementary forms of power.","source":"Black AF History","source_section":"Mary McLeod Bethune section"},{"id":"V1-031","subject":"A. Philip Randolph","kind":"thinker_organizer","world":"ORGANIZING","era":"1940s","core_idea":"Randolph used the credible threat of mass protest to increase pressure on federal officials over employment discrimination.","share":"Randolph’s leverage came from people organized behind the threat.","lens":"Access matters differently when an organizer also has an independent base of support.","source":"Black AF History","source_section":"Bethune / Randolph / Executive Order 8802 discussion"},{"id":"V1-032","subject":"Brown v. Board","kind":"historical_idea","world":"POWER","era":"1950s","core_idea":"Brown overturned the constitutional basis for school segregation, while demonstrating that changing the legal rule and changing institutions are separate tasks.","share":"Brown changed the rule before it changed the reality.","lens":"After any reform, ask separately what changed in law and what changed in practice.","source":"Four Hundred Souls","source_section":"1949–1954: The Road to Brown v. Board"},{"id":"V1-033","subject":"Montgomery 1955 — organizer, action, symbol","kind":"case","world":"ORGANIZING","era":"1955","core_idea":"Claudette Colvin, Rosa Parks, Jo Ann Robinson, the Women’s Political Council, lawyers, and local networks show that the person who acts, the person who organizes, and the person who becomes the symbol may be different people.","share":"Parks became the symbol because organizers were already prepared to move.","lens":"When a movement looks spontaneous, ask who had the network ready beforehand.","source":"Black AF History","source_section":"Women who desegregated Montgomery buses"},{"id":"V1-034","subject":"Ella Baker","kind":"thinker","world":"ORGANIZING","era":"1950s–1960s","core_idea":"Baker favored participatory leadership that increased ordinary people’s capacity to act rather than concentrating a movement around a single public figure.","share":"Baker thought strong leadership should create more leaders.","lens":"If the visible leader vanished, would the organization still know how to act?","source":"Black AF History + Four Hundred Souls","source_section":"Ella Baker / Civil Rights Movement chapters"},{"id":"V1-035","subject":"Martin Luther King Jr. — nonviolent resistance","kind":"thinker","world":"POWER","era":"1950s–1960s","core_idea":"King treated disciplined nonviolent resistance as an organizing strategy for confronting injustice publicly, mobilizing broad participation, and applying moral and political pressure.","share":"King’s nonviolence was a method of resistance, not passive acceptance.","lens":"A tactic can reject violence while still being confrontational.","source":"Black AF History + Four Hundred Souls","source_section":"Civil Rights Movement / Black Power discussions"},{"id":"V1-036","subject":"Malcolm X","kind":"thinker","world":"FREEDOM","era":"1950s–1960s","core_idea":"Malcolm X emphasized Black dignity, self-determination, international human rights, and an analysis of Black struggle that extended beyond U.S. citizenship alone.","share":"Malcolm moved the freedom struggle onto a global human-rights map.","lens":"A thinker can change strategy while keeping the underlying problem in view.","source":"Black AF History + Four Hundred Souls","source_section":"Malcolm X / Black Power chapters"},{"id":"V1-037","subject":"Stokely Carmichael / Kwame Ture","kind":"thinker","world":"POWER","era":"1960s","core_idea":"Carmichael/Ture emphasized Black political self-determination and evolved from civil-rights organizing toward Black Power and Pan-Africanism.","share":"Carmichael shifted the question from inclusion to political control.","lens":"Representation and agenda-setting power are not the same thing.","source":"Black AF History + Four Hundred Souls","source_section":"Black Power chapters"},{"id":"V1-038","subject":"Fred Hampton","kind":"thinker_organizer","world":"ORGANIZING","era":"1960s","core_idea":"Hampton linked political education, community programs, and coalition across racial and ethnic groups around shared material interests.","share":"Hampton built coalition around concrete needs, not vague solidarity.","lens":"Coalitions are easier to sustain when groups know what they are trying to win together.","source":"Black AF History","source_section":"Fred Hampton / COINTELPRO section"},{"id":"V1-039","subject":"Combahee River Collective","kind":"collective_thought","world":"IDENTITY","era":"1970s","core_idea":"Combahee argued that race, gender, class, and sexuality could operate simultaneously; Black women could build politics from their own position while still forming coalitions.","share":"Combahee asked politics to see Black women whole, not one category at a time.","lens":"If a movement helps one part of a group, ask whose experience its analysis may still miss.","source":"Four Hundred Souls","source_section":"1974–1979: Combahee River Collective"},{"id":"V1-040","subject":"Hip-hop generation","kind":"cultural_idea","world":"CULTURE","era":"1980s","core_idea":"Hip-hop became a space where a new generation narrated Black urban life, politics, creativity, alienation, and identity outside older movement forms.","share":"Hip-hop became a political language without needing to look like a political meeting.","lens":"A generation may build its intellectual vocabulary through culture before institutions recognize it as thought.","source":"Four Hundred Souls","source_section":"1984–1989: The Hip-Hop Generation"},{"id":"V1-041","subject":"Anita Hill and Black women’s public voice","kind":"historical_idea","world":"IDENTITY","era":"1990s","core_idea":"The Anita Hill hearings forced public debate over race, gender, sexual harassment, credibility, and whether Black women’s experiences could be subordinated to other political loyalties.","share":"Anita Hill exposed what happens when race and gender demand different loyalties.","lens":"When two forms of injustice intersect, single-issue politics can leave people without a full language for their experience.","source":"Four Hundred Souls","source_section":"1989–1994: Anita Hill"},{"id":"V1-042","subject":"Black immigrant identity","kind":"historical_idea","world":"IDENTITY","era":"1990s–2000s","core_idea":"Blackness in the United States includes immigrants whose national, ethnic, and racial identities interact with a U.S. racial system that may read them simply as Black.","share":"Black identity can unite people without erasing where they came from.","lens":"A broad identity can create solidarity while still containing many histories inside it.","source":"Four Hundred Souls","source_section":"1999–2004: The Black Immigrant"},{"id":"V1-043","subject":"Voting rights after Shelby","kind":"historical_idea","world":"POWER","era":"2000s–2010s","core_idea":"The history of voting rights shows that legal protections can be weakened or reinterpreted after major victories, making political rights an ongoing institutional question.","share":"Voting rights can expand, contract, and require protection again.","lens":"A right’s existence and the durability of the institutions protecting it are different questions.","source":"Four Hundred Souls","source_section":"2009–2014: The Shelby Ruling"},{"id":"V1-044","subject":"Black Lives Matter — organizational form","kind":"movement_idea","world":"ORGANIZING","era":"2010s","core_idea":"Black Lives Matter drew on Black feminist and grassroots traditions while using decentralized networks to organize in a media environment very different from mid-century movements.","share":"Modern movements inherited old questions about leadership, power, and whose lives count.","lens":"Compare how decentralized and leader-centered organizations handle speed, accountability, visibility, and continuity.","source":"Four Hundred Souls","source_section":"2014–2019: Black Lives Matter"}],"context_cards":[{"id":"CTX-01","title":"The Constitution and slavery","purpose":"Background for founding-era freedom and later citizenship debates."},{"id":"CTX-02","title":"Lynching and racial terror","purpose":"Background for Wells, Washington, migration, and Black political strategy."},{"id":"CTX-03","title":"COINTELPRO","purpose":"Background for King, Malcolm X, Hampton, Carmichael/Ture, and Black Power."},{"id":"CTX-04","title":"Jim Crow","purpose":"Background for Plessy, Washington, Wells, Great Migration, and civil-rights strategy."},{"id":"CTX-05","title":"The War on Drugs and mass incarceration","purpose":"Late-twentieth-century background without turning policy history into a thinker node."},{"id":"CTX-06","title":"Hurricane Katrina","purpose":"Modern context for state capacity, race, place, inequality, and public institutions."},{"id":"CTX-07","title":"Civil Rights Act / Voting Rights Act","purpose":"Legal context for civil-rights victories and later debates about implementation and durability."}],"debates":[{"id":"D-01","title":"Washington ↔ Du Bois","question":"What should education and Black advancement prioritize?","rule":"Present both strategies in their historical setting; do not designate a winner."},{"id":"D-02","title":"Washington ↔ Wells","question":"What strategy makes sense when racial terror is the immediate threat?","rule":"Compare diagnoses and available leverage; do not caricature Washington."},{"id":"D-03","title":"Baker ↔ King","question":"How should movement leadership work?","rule":"Compare grassroots leadership development with the advantages of visible centralized leadership."},{"id":"D-04","title":"King ↔ Malcolm X","question":"How should resistance relate to nonviolence, self-defense, citizenship, and human rights?","rule":"Use dated positions because both thinkers evolved."},{"id":"D-05","title":"Integration ↔ Black Power","question":"Is access to institutions enough, or is control over decisions the deeper goal?","rule":"Treat this as a strategic distinction, not a moral scorecard."},{"id":"D-06","title":"Hurston ↔ protest-art tradition","question":"What does Black art owe to political struggle?","rule":"Do not invent a single opponent; use the Harlem Renaissance/Black Arts context until a source-supported thinker pair is added."},{"id":"D-07","title":"Combahee ↔ male-centered liberation politics","question":"What gets missed when race politics treats men’s experience as the default?","rule":"Use the source’s documented critique; do not reduce all Black nationalism to one position."}],"threads":[{"id":"T-01","title":"LEAVE · REFORM · BUILD","path":["Marronage/Fort Mose","Great Migration","Brown/Reconstruction","Bethune","Black Power"],"question":"Do you leave an oppressive institution, reform it, or build another one?"},{"id":"T-02","title":"LEVERAGE","path":["Wells boycotts","Randolph protest threat","Montgomery boycott","Hampton coalition"],"question":"How do people without formal authority make powerful institutions respond?"},{"id":"T-03","title":"EVIDENCE AS RESISTANCE","path":["McCune Smith","Ida B. Wells","Du Bois"],"question":"How can research challenge ideas presented as objective truth?"},{"id":"T-04","title":"WHAT IS EDUCATION FOR?","path":["Wheatley","Douglass","Washington","Bethune","Baker","Hampton"],"question":"Is education for literacy, livelihood, leadership, institutions, political consciousness—or several at once?"},{"id":"T-05","title":"WHO BUILT IT?","path":["National Negro Conventions","Montgomery","Baker","Boynton/context","BLM"],"question":"What invisible infrastructure sits underneath the famous event or leader?"},{"id":"T-06","title":"WHO DEFINES BLACKNESS?","path":["African identities","Du Bois","Harlem Renaissance","Hurston","Baldwin","Hip-hop","Black immigrant identity"],"question":"Who gets to define what Black life means?"},{"id":"T-07","title":"LEGAL VICTORY · LIVED REALITY","path":["Reconstruction","Plessy","Brown","Voting Rights","Shelby"],"question":"What changes when the law changes—and what does not?"}],"framing":[{"id":"F-01","title":"The books teach the game; the game does not quiz the books.","text":"Source authors remain backstage unless deliberately selected as thinkers."},{"id":"F-02","title":"History has a point of view.","text":"Use this as an onboarding premise, not a mastery node."}],"future_source_check_candidates":["Anna Julia Cooper as a full thinker node — current source supports her importance but not enough of her ideas for a strong standalone card.","Marcus and Amy Jacques Garvey / UNIA — current source confirms presence and influence but a fuller idea node needs deeper source extraction or outside supplementation.","Audre Lorde — named in Combahee context but requires more direct idea material.","Richard Wright / Langston Hughes as a named art-debate counterpart — verify enough direct source material before adding.","Pauli Murray — appears as an earlier sit-in organizer but needs a fuller source-supported idea before becoming a thinker node."],"counts":{"playable_nodes":44,"context_cards":7,"debates":7,"threads":7,"world_distribution":{"IDENTITY":6,"POWER":10,"ECONOMICS":4,"FREEDOM":5,"CULTURE":6,"EDUCATION":5,"ORGANIZING":8}}},"playtest":{"project":"BLACK FOLK","version":"V1.1 tuned playtest set","encounter_count":40,"session_design":{"target_minutes":"5–8","default_encounters_per_session":6,"recommended_mix":"2 discovery/new + 2 retrieval/review + 1 connection/context + 1 higher-order encounter","points":{"discover_or_easy_recognition":10,"context_or_basic_connection":15,"recall_or_application":20,"hard_connection_or_share":25,"advanced_debate":30,"boss_round":50},"feedback":"Show +Knowledge briefly, then disappear. Do not add extra currencies.","mastery_logic":"Points reward play; mastery tracks what the player actually knows. Missed items return sooner. Recall-before-reveal and share cards use self-rating.","pacing_rules":["Never show more than two standard multiple-choice encounters in a row.","New concepts should usually appear first as a short DISCOVER card, then be tested later.","Keep ordinary prompt text under ~28 words when possible.","Keep ordinary reveals to 1–2 short sentences.","Use three answer choices when a fourth choice adds no useful discrimination.","Do not use a debate as the first exposure to either thinker.","End every session with KEEP THIS, not another quiz."],"new_player_onboarding":"Use three curated starter sessions before fully adaptive play. Teach the interface without explaining the scheduling system."},"modes":{"WHAT":"recognize an idea","WHO":"identify a thinker","CONNECT":"link thinkers, ideas, or strategies","SAME QUESTION":"compare historically grounded answers without choosing a political winner","RECALL":"think first, reveal, self-rate","SHARE":"explain aloud, reveal model, self-rate","THEN → NOW":"apply an old lens to a generic present-day scenario","TIMELINE":"place ideas/events in sequence","BOSS ROUND":"multi-node synthesis after prerequisites","WHY THEN":"connect idea to the historical circumstances that made it significant","DISCOVER":"brief first exposure to a strong idea; tap to continue","MATCH":"drag or tap to match thinkers with ideas; no typing"},"encounters":[{"id":"E001","mode":"WHAT","prompt":"Black history in America does not begin with enslavement. Which idea follows?","answers":["Black history begins with the Civil War.","Black American history sits inside a longer African history.","Black history begins with the Great Migration.","Black history is mainly a history of U.S. law."],"correct_answer":"Black American history sits inside a longer African history.","reveal":"Enslavement is a rupture in a longer African history, not the beginning of Black existence.","points":10,"node_ids":["V1-001"],"difficulty":"easy","mastery":["UNDERSTAND"],"design_note":"","source":"Four Hundred Souls — 1624–1629: Africa","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"ANSWER"},{"id":"E002","mode":"WHO","prompt":"Who described the strain of seeing yourself through your own eyes and through a society that devalues Blackness?","answers":["W.E.B. Du Bois","Booker T. Washington","Frederick Douglass","James Baldwin"],"correct_answer":"W.E.B. Du Bois","reveal":"Du Bois called this tension double consciousness.","points":10,"node_ids":["V1-019"],"difficulty":"easy","mastery":["RECALL"],"design_note":"","source":"Black AF History — Introduction / The Souls of Black Folk","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"ANSWER"},{"id":"E003","mode":"WHAT","prompt":"Ella Baker’s model of strong leadership was closest to…","answers":["create more leaders","protect one central spokesperson","avoid local organizations","focus on elections only"],"correct_answer":"create more leaders","reveal":"Baker favored participatory leadership that increased ordinary people’s capacity to act.","points":10,"node_ids":["V1-034"],"difficulty":"easy","mastery":["UNDERSTAND"],"design_note":"","source":"Black AF History + Four Hundred Souls — Ella Baker / Civil Rights Movement","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"ANSWER"},{"id":"E004","mode":"CONNECT","prompt":"Which pair belongs together?","answers":["Ida B. Wells → investigative reporting and anti-lynching evidence","Zora Neale Hurston → federal employment policy","Mary McLeod Bethune → maroon settlements","Fred Hampton → the Harlem Renaissance"],"correct_answer":"Ida B. Wells → investigative reporting and anti-lynching evidence","reveal":"Wells used reporting and statistics to challenge the stories used to justify lynching.","points":15,"node_ids":["V1-021"],"difficulty":"easy","mastery":["CONNECT"],"design_note":"","source":"Black AF History — Ida B. Wells section","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"ANSWER"},{"id":"E005","mode":"WHY THEN","prompt":"Why does Reconstruction matter to the meaning of freedom?","answers":["It shows that ending slavery did not settle questions of citizenship and power.","It was the beginning of the Atlantic slave trade.","It created the Harlem Renaissance.","It ended all legal segregation immediately."],"correct_answer":"It shows that ending slavery did not settle questions of citizenship and power.","reveal":"Emancipation answered whether slavery would continue. Reconstruction raised the harder question of what freedom would require next.","points":15,"node_ids":["V1-015"],"difficulty":"easy","mastery":["CONTEXTUALIZE"],"design_note":"","source":"Four Hundred Souls + Black AF History — Reconstruction","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"ANSWER"},{"id":"E006","mode":"WHAT","prompt":"Freedom’s Journal mattered because it gave Black communities…","answers":["a Black-controlled platform for self-representation","the first federal voting law","a national labor union","the first integrated university"],"correct_answer":"a Black-controlled platform for self-representation","reveal":"Black-controlled media meant Black people did not have to rely entirely on outside institutions to define Black life.","points":10,"node_ids":["V1-010"],"difficulty":"easy","mastery":["UNDERSTAND"],"design_note":"","source":"Four Hundred Souls — 1824–1829: Freedom’s Journal","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"ANSWER"},{"id":"E007","mode":"WHAT","prompt":"Booker T. Washington’s strategy emphasized…","answers":["industrial education and economic strength","armed insurrection","decentralized student leadership","literary modernism"],"correct_answer":"industrial education and economic strength","reveal":"Washington emphasized education, work, and economic advancement in a hostile political environment.","points":10,"node_ids":["V1-018"],"difficulty":"easy","mastery":["UNDERSTAND"],"design_note":"","source":"Four Hundred Souls + Black AF History — Booker T. Washington","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"ANSWER"},{"id":"E008","mode":"WHAT","prompt":"Which idea best fits Zora Neale Hurston?","answers":["Black life could be worthy of art without always becoming a protest message.","Black art should only address electoral politics.","Black culture should avoid folklore and vernacular.","Art should be replaced by political organizing."],"correct_answer":"Black life could be worthy of art without always becoming a protest message.","reveal":"Hurston treated Black vernacular, folklore, humor, and ordinary life as worthy subjects on their own terms.","points":10,"node_ids":["V1-027"],"difficulty":"easy","mastery":["UNDERSTAND"],"design_note":"","source":"Four Hundred Souls — Zora Neale Hurston","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"ANSWER"},{"id":"E009","mode":"CONNECT","prompt":"Which connection is strongest?","answers":["James McCune Smith → evidence against racial pseudoscience","Fred Hampton → Plessy v. Ferguson","Malcolm X → Freedom’s Journal","Phillis Wheatley → Montgomery bus organizing"],"correct_answer":"James McCune Smith → evidence against racial pseudoscience","reveal":"McCune Smith used scholarship and professional expertise to challenge supposedly scientific claims of Black inferiority.","points":15,"node_ids":["V1-013"],"difficulty":"easy","mastery":["CONNECT"],"design_note":"","source":"Four Hundred Souls — James McCune Smith, M.D.","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"ANSWER"},{"id":"E010","mode":"RECALL","prompt":"Think before revealing:\n\nWhat is the simplest difference between legal victory and lived reality?","answers":[],"correct_answer":null,"reveal":"A rule can change before institutions, resources, habits, or power change with it.\n\nSELF-RATE: KNEW IT / ALMOST / MISSED","points":20,"node_ids":["V1-032"],"difficulty":"easy","mastery":["RECALL","SHARE"],"design_note":"","source":"Four Hundred Souls — Brown v. Board","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"ANSWER"},{"id":"E011","mode":"SAME QUESTION","prompt":"Wells and Washington wanted Black advancement. Where did their diagnoses differ?","answers":["Wells emphasized racial power and terror; Washington emphasized education and economic advancement.","Wells rejected education; Washington rejected economics.","Wells opposed journalism; Washington supported it.","They had identical diagnoses."],"correct_answer":"Wells emphasized racial power and terror; Washington emphasized education and economic advancement.","reveal":"The important point is not to crown a winner. Different diagnoses produce different strategies.","points":25,"node_ids":["V1-018","V1-021","V1-022"],"difficulty":"medium","mastery":["CONNECT","CONTEXTUALIZE"],"design_note":"","source":"Black AF History + Four Hundred Souls","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"BEST FIT","unlock_rule":"Only after all linked nodes have been introduced at least once."},{"id":"E012","mode":"CONNECT","prompt":"Which thread connects Freedom’s Journal and Ida B. Wells?","answers":["self-representation through Black-controlled media","industrial education","nonviolent resistance","migration to the North"],"correct_answer":"self-representation through Black-controlled media","reveal":"Both show media as power: owning or controlling the means of telling the story changes who gets to define Black life.","points":20,"node_ids":["V1-010","V1-021"],"difficulty":"medium","mastery":["CONNECT"],"design_note":"","source":"Four Hundred Souls + Black AF History","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"ANSWER"},{"id":"E013","mode":"WHY THEN","prompt":"What did the Atlanta washerwomen gain by organizing common rates and a protective association?","answers":["more collective control over their labor","automatic voting rights","federal government jobs","ownership of the railroads"],"correct_answer":"more collective control over their labor","reveal":"Their organizing turned individually negotiated domestic labor into coordinated economic leverage.","points":15,"node_ids":["V1-016"],"difficulty":"medium","mastery":["CONTEXTUALIZE","UNDERSTAND"],"design_note":"","source":"Four Hundred Souls — Atlanta washerwomen","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"ANSWER"},{"id":"E014","mode":"SAME QUESTION","prompt":"Baker and King emphasized different strengths in leadership. Which contrast is fairest?","answers":["grassroots leadership development vs. visible centralized leadership","education vs. no education","violence vs. no politics","culture vs. economics"],"correct_answer":"grassroots leadership development vs. visible centralized leadership","reveal":"Baker stressed building leadership from below. King’s public leadership could concentrate attention, fundraising, and national pressure. The tradeoff matters more than picking a winner.","points":25,"node_ids":["V1-034","V1-035"],"difficulty":"medium","mastery":["CONNECT","APPLY"],"design_note":"","source":"Black AF History + Four Hundred Souls","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"BEST FIT","unlock_rule":"Only after all linked nodes have been introduced at least once."},{"id":"E015","mode":"WHAT","prompt":"What made Mary McLeod Bethune’s strategy distinctive?","answers":["She combined Black institution-building with access to federal decision-makers.","She rejected institutions entirely.","She focused only on literature.","She opposed all work with government."],"correct_answer":"She combined Black institution-building with access to federal decision-makers.","reveal":"Bethune shows that independent institutions and insider access can work together rather than cancel each other out.","points":15,"node_ids":["V1-030"],"difficulty":"medium","mastery":["UNDERSTAND","CONNECT"],"design_note":"","source":"Black AF History — Mary McLeod Bethune","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"ANSWER"},{"id":"E016","mode":"CONNECT","prompt":"Which pair best fits the thread EVIDENCE AS RESISTANCE?","answers":["James McCune Smith + Ida B. Wells","Fred Hampton + Zora Neale Hurston","Booker T. Washington + the spirituals","Malcolm X + Phillis Wheatley"],"correct_answer":"James McCune Smith + Ida B. Wells","reveal":"Both used evidence to confront ideas that were presented as objective truth.","points":20,"node_ids":["V1-013","V1-021"],"difficulty":"medium","mastery":["CONNECT"],"design_note":"","source":"Four Hundred Souls + Black AF History","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"ANSWER"},{"id":"E017","mode":"WHAT","prompt":"What did Malcolm X add to the freedom struggle in this curriculum?","answers":["a global human-rights and self-determination frame","a theory of industrial education","a legal defense of separate but equal","a rejection of Black political identity"],"correct_answer":"a global human-rights and self-determination frame","reveal":"Malcolm increasingly situated Black struggle within international human rights, anticolonialism, and self-determination.","points":15,"node_ids":["V1-036"],"difficulty":"medium","mastery":["UNDERSTAND"],"design_note":"","source":"Black AF History + Four Hundred Souls — Malcolm X / Black Power","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"ANSWER"},{"id":"E018","mode":"TIMELINE","prompt":"Put these in chronological order.","answers":["Freedom’s Journal → Reconstruction → Harlem Renaissance → Black Power"],"correct_answer":"Freedom’s Journal → Reconstruction → Harlem Renaissance → Black Power","reveal":"1820s → 1860s–70s → 1920s → 1960s.","points":15,"node_ids":["V1-010","V1-015","V1-026","V1-037"],"difficulty":"medium","mastery":["CONTEXTUALIZE"],"design_note":"UI should render four draggable cards.","source":"Curriculum timeline","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"ANSWER"},{"id":"E019","mode":"WHAT","prompt":"Why keep Plessy in the game even though the court challenge failed?","answers":["Because it shows organized Black resistance as well as the legal power of segregation.","Because Plessy ended segregation.","Because it founded the NAACP.","Because it created Black Power."],"correct_answer":"Because it shows organized Black resistance as well as the legal power of segregation.","reveal":"The case matters both for the doctrine it produced and for the Black organizing that challenged segregation.","points":15,"node_ids":["V1-017"],"difficulty":"medium","mastery":["CONTEXTUALIZE"],"design_note":"","source":"Four Hundred Souls — Plessy v. Ferguson","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"ANSWER"},{"id":"E020","mode":"RECALL","prompt":"Think before revealing:\n\nWhat was Callie House trying to turn reparations into?","answers":[],"correct_answer":null,"reveal":"A mass movement with chapters, members, agents, and community institutions—not just an elite policy demand.\n\nSELF-RATE: KNEW IT / ALMOST / MISSED","points":20,"node_ids":["V1-024"],"difficulty":"medium","mastery":["RECALL","SHARE"],"design_note":"","source":"Black AF History — ex-slave pension movement","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"ANSWER"},{"id":"E021","mode":"CONNECT","prompt":"Which sequence best illustrates the LEVERAGE thread?","answers":["Wells boycott → Randolph protest threat → Montgomery boycott","Hurston folklore → Brown v. Board → Wheatley poetry","Plessy → Du Bois double consciousness → hip-hop","Fort Mose → Booker T. Washington → Baldwin"],"correct_answer":"Wells boycott → Randolph protest threat → Montgomery boycott","reveal":"Each case asks how people without formal authority can create costs or pressure that powerful institutions must answer.","points":25,"node_ids":["V1-022","V1-031","V1-033"],"difficulty":"hard","mastery":["CONNECT","APPLY"],"design_note":"","source":"Cross-source curriculum thread","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"ANSWER","unlock_rule":"Only after all linked nodes have been introduced at least once."},{"id":"E022","mode":"SAME QUESTION","prompt":"Integration and Black Power asked different questions. Which pairing is most accurate?","answers":["Integration: who can enter? Black Power: who can decide?","Integration: who can vote? Black Power: who can read?","Integration: who can sing? Black Power: who can migrate?","They asked exactly the same question."],"correct_answer":"Integration: who can enter? Black Power: who can decide?","reveal":"Access and control are not identical. A person may gain entry into an institution without gaining much influence over its decisions.","points":25,"node_ids":["V1-032","V1-037"],"difficulty":"hard","mastery":["CONNECT","APPLY"],"design_note":"","source":"Four Hundred Souls + Black AF History","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"BEST FIT","unlock_rule":"Only after all linked nodes have been introduced at least once."},{"id":"E023","mode":"WHAT","prompt":"Combahee’s key analytical move was to…","answers":["treat race, gender, class, and sexuality as potentially operating together","argue that only class mattered","reject coalition with everyone outside Black feminism","separate identity from politics entirely"],"correct_answer":"treat race, gender, class, and sexuality as potentially operating together","reveal":"Combahee argued that Black women’s lives could not be understood by examining one form of domination at a time.","points":15,"node_ids":["V1-039"],"difficulty":"medium","mastery":["UNDERSTAND"],"design_note":"","source":"Four Hundred Souls — Combahee River Collective","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"ANSWER"},{"id":"E024","mode":"CONNECT","prompt":"Why does Claudette Colvin connect well to Combahee?","answers":["Her treatment shows how race, gender, age, class, and respectability could shape whose story became usable.","She founded the Combahee River Collective.","She opposed bus desegregation.","She was a Black Power theorist."],"correct_answer":"Her treatment shows how race, gender, age, class, and respectability could shape whose story became usable.","reveal":"Colvin makes an abstract idea concrete: movements can treat people differently depending on several identities and social expectations at once.","points":20,"node_ids":["V1-033","V1-039"],"difficulty":"hard","mastery":["CONNECT","APPLY"],"design_note":"","source":"Black AF History + Four Hundred Souls","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"ANSWER","unlock_rule":"Only after all linked nodes have been introduced at least once."},{"id":"E025","mode":"WHAT","prompt":"Fred Hampton’s coalition politics depended most on…","answers":["shared concrete interests plus political education","celebrity leadership alone","avoiding economic issues","keeping racial groups permanently separate"],"correct_answer":"shared concrete interests plus political education","reveal":"Hampton linked community programs, political education, and cross-racial coalition around material needs.","points":15,"node_ids":["V1-038"],"difficulty":"medium","mastery":["UNDERSTAND"],"design_note":"","source":"Black AF History — Fred Hampton","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"ANSWER"},{"id":"E026","mode":"CONNECT","prompt":"Which three nodes best fit the question: WHAT IS EDUCATION FOR?","answers":["Douglass, Washington, Baker","Hurston, Plessy, Fort Mose","Malcolm X, Freedom’s Journal, Katrina","Combahee, Great Migration, spirituals"],"correct_answer":"Douglass, Washington, Baker","reveal":"Douglass links literacy to freedom; Washington emphasizes skills and economic advancement; Baker uses education to develop people capable of acting.","points":20,"node_ids":["V1-014","V1-018","V1-034"],"difficulty":"hard","mastery":["CONNECT"],"design_note":"","source":"Cross-source curriculum thread","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"ANSWER","unlock_rule":"Only after all linked nodes have been introduced at least once."},{"id":"E027","mode":"RECALL","prompt":"Think before revealing:\n\nWhat is the core difference between individual mobility and collective freedom?","answers":[],"correct_answer":null,"reveal":"An individual can advance while the rules or conditions facing the wider group remain largely unchanged.\n\nSELF-RATE: KNEW IT / ALMOST / MISSED","points":20,"node_ids":["V1-014","V1-018"],"difficulty":"hard","mastery":["RECALL","APPLY"],"design_note":"","source":"Curriculum lens","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"ANSWER"},{"id":"E028","mode":"WHAT","prompt":"Why does hip-hop belong in an intellectual-history game?","answers":["Culture can carry social analysis, identity, politics, and generational argument.","Only written essays count as thought.","Hip-hop replaced all previous Black movements.","It belongs only as entertainment history."],"correct_answer":"Culture can carry social analysis, identity, politics, and generational argument.","reveal":"The game treats culture as one place Black people think publicly—not merely as decoration around formal politics.","points":15,"node_ids":["V1-040"],"difficulty":"medium","mastery":["UNDERSTAND","APPLY"],"design_note":"","source":"Four Hundred Souls — The Hip-Hop Generation","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"ANSWER"},{"id":"E029","mode":"WHY THEN","prompt":"Why does the Anita Hill episode matter beyond one person’s biography?","answers":["It makes race-and-gender conflict inside political loyalty visible.","It explains the Great Migration.","It is mainly about industrial education.","It teaches the origins of Reconstruction."],"correct_answer":"It makes race-and-gender conflict inside political loyalty visible.","reveal":"The episode forces a question central to Black feminist thought: what happens when a person belongs to more than one political category at once?","points":15,"node_ids":["V1-041"],"difficulty":"hard","mastery":["CONTEXTUALIZE","APPLY"],"design_note":"","source":"Four Hundred Souls — Anita Hill","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"ANSWER"},{"id":"E030","mode":"CONNECT","prompt":"Which pairing best illustrates WHO DEFINES BLACKNESS?","answers":["Du Bois + Hurston","Randolph + Plessy","Bethune + Brown","Vesey + washerwomen"],"correct_answer":"Du Bois + Hurston","reveal":"Du Bois explored how Black people see themselves through a society that judges them; Hurston insisted Black life could be represented on its own terms.","points":20,"node_ids":["V1-019","V1-027"],"difficulty":"hard","mastery":["CONNECT"],"design_note":"","source":"Black AF History + Four Hundred Souls","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"ANSWER","unlock_rule":"Only after all linked nodes have been introduced at least once."},{"id":"E031","mode":"SHARE","prompt":"30 SECONDS\n\nExplain this idea aloud:\n\n“Brown changed the rule before it changed the reality.”","answers":[],"correct_answer":null,"reveal":"MODEL: Brown made school segregation unconstitutional, but institutions and communities still had to implement desegregation against enormous resistance.\n\nSELF-RATE: CLEAR / ALMOST / NEEDS WORK","points":25,"node_ids":["V1-032"],"difficulty":"hard","mastery":["SHARE"],"design_note":"","source":"Four Hundred Souls — Brown v. Board","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"ANSWER","unlock_rule":"Only after the linked idea has been answered/recalled correctly at least once."},{"id":"E032","mode":"SHARE","prompt":"30 SECONDS\n\nExplain why Freedom’s Journal was a form of power.","answers":[],"correct_answer":null,"reveal":"MODEL: A Black-controlled newspaper let Black people describe their own lives, priorities, and arguments instead of depending on outsiders to define them.\n\nSELF-RATE: CLEAR / ALMOST / NEEDS WORK","points":25,"node_ids":["V1-010"],"difficulty":"medium","mastery":["SHARE"],"design_note":"","source":"Four Hundred Souls — Freedom’s Journal","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"ANSWER","unlock_rule":"Only after the linked idea has been answered/recalled correctly at least once."},{"id":"E033","mode":"SAME QUESTION","prompt":"King and Malcolm X both addressed Black freedom. Which introductory contrast is fairest?","answers":["King emphasized disciplined nonviolent resistance and U.S. citizenship; Malcolm increasingly framed the struggle through self-determination and international human rights.","King opposed all protest; Malcolm supported only elections.","King rejected citizenship; Malcolm rejected human rights.","They never differed strategically."],"correct_answer":"King emphasized disciplined nonviolent resistance and U.S. citizenship; Malcolm increasingly framed the struggle through self-determination and international human rights.","reveal":"This is a starting comparison, not a permanent box. Both thinkers changed over time, so later encounters should show their evolution.","points":30,"node_ids":["V1-035","V1-036"],"difficulty":"hard","mastery":["CONNECT","CONTEXTUALIZE"],"design_note":"","source":"Black AF History + Four Hundred Souls","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"BEST FIT","unlock_rule":"Only after all linked nodes have been introduced at least once."},{"id":"E034","mode":"CONNECT","prompt":"Which two figures best illustrate inside access and outside pressure working together?","answers":["Mary McLeod Bethune + A. Philip Randolph","Hurston + Wheatley","Baker + Baldwin","Vesey + Plessy"],"correct_answer":"Mary McLeod Bethune + A. Philip Randolph","reveal":"Bethune had access to federal decision-makers. Randolph brought organized outside pressure. Different forms of leverage could reinforce each other.","points":25,"node_ids":["V1-030","V1-031"],"difficulty":"hard","mastery":["CONNECT"],"design_note":"","source":"Black AF History — Bethune / Randolph","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"ANSWER","unlock_rule":"Only after all linked nodes have been introduced at least once."},{"id":"E035","mode":"THEN → NOW","prompt":"LENS\n\nA group is invited into an institution but has little influence over the rules.\n\nWhich older question does this most closely echo?","answers":["access vs. control","art vs. folklore","migration vs. literacy","faith vs. journalism"],"correct_answer":"access vs. control","reveal":"This is the same distinction the curriculum uses to connect integration and Black Power: being present is not identical to setting the agenda.","points":20,"node_ids":["V1-037"],"difficulty":"hard","mastery":["APPLY"],"design_note":"This is an abstract present-day transfer, not a claim about any specific current political institution.","source":"Curriculum lens","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"ANSWER"},{"id":"E036","mode":"THEN → NOW","prompt":"LENS\n\nA public story blames a community for an outcome. Before accepting it, what would Ida B. Wells push you to ask first?","answers":["What do the facts and data actually show?","Who is the most famous spokesperson?","Which slogan sounds strongest?","Can the story be made shorter?"],"correct_answer":"What do the facts and data actually show?","reveal":"Wells’s anti-lynching work repeatedly attacked the narratives used to justify violence by checking them against evidence.","points":20,"node_ids":["V1-021"],"difficulty":"medium","mastery":["APPLY"],"design_note":"","source":"Black AF History — Ida B. Wells","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"ANSWER"},{"id":"E037","mode":"CONNECT","prompt":"Which sequence best fits LEAVE · REFORM · BUILD?","answers":["Marronage → Brown v. Board → Bethune / Black institutions","Wells → Wheatley → Plessy","Baldwin → Vesey → Randolph","Hip-hop → Reconstruction → spirituals"],"correct_answer":"Marronage → Brown v. Board → Bethune / Black institutions","reveal":"The thread asks whether freedom is pursued by leaving an oppressive structure, changing it, or creating institutions with more autonomy.","points":25,"node_ids":["V1-004","V1-032","V1-030"],"difficulty":"hard","mastery":["CONNECT","APPLY"],"design_note":"","source":"Cross-source curriculum thread","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"ANSWER","unlock_rule":"Only after all linked nodes have been introduced at least once."},{"id":"E038","mode":"RECALL","prompt":"Think before revealing:\n\nWhat did Du Bois’s Black Reconstruction change about the story of emancipation?","answers":[],"correct_answer":null,"reveal":"It centered Black agency—especially enslaved people withdrawing labor and joining the freedom struggle—rather than treating emancipation as something simply handed down from above.\n\nSELF-RATE: KNEW IT / ALMOST / MISSED","points":25,"node_ids":["V1-020"],"difficulty":"hard","mastery":["RECALL","CONTEXTUALIZE"],"design_note":"","source":"Black AF History — Black Reconstruction / 'The General Strike'","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"ANSWER"},{"id":"E039","mode":"SHARE","prompt":"30 SECONDS\n\nExplain this line:\n\n“Protest creates attention. Organization creates continuity.”","answers":[],"correct_answer":null,"reveal":"MODEL: A protest can make an issue visible, but durable change usually requires people, relationships, institutions, and routines that still exist after the event ends.\n\nSELF-RATE: CLEAR / ALMOST / NEEDS WORK","points":30,"node_ids":["V1-012","V1-024","V1-034","V1-038"],"difficulty":"hard","mastery":["SHARE","CONNECT"],"design_note":"","source":"Cross-source organizing thread","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"ANSWER","unlock_rule":"Only after the linked idea has been answered/recalled correctly at least once."},{"id":"E040","mode":"MATCH","prompt":"BOSS ROUND · WHAT IS EDUCATION FOR?\n\nMatch each thinker to the emphasis this curriculum has introduced.","answers":["Douglass → literacy and citizenship","Washington → practical skills and economic strength","Bethune → durable institutions and access","Baker / Hampton → people prepared to organize and act"],"correct_answer":"All four matches","reveal":"Different eras produced different answers to the same question. Mastery here means holding several answers at once—not choosing a winner.","points":50,"node_ids":["V1-014","V1-018","V1-030","V1-034","V1-038"],"difficulty":"boss","mastery":["UNDERSTAND","CONNECT","CONTEXTUALIZE","APPLY"],"design_note":"Render as four draggable thinker chips and four idea targets. Unlock after at least four linked nodes have been encountered.","source":"Cross-source EDUCATION thread","ui_feedback":{"success":"brief +KNOWLEDGE animation","miss":"show answer/reveal calmly; no red punishment screen","next":"one tap"},"answer_label":"MATCH","unlock_rule":"Only after all linked nodes have been introduced at least once."}],"discovery_cards":[{"id":"D001","mode":"DISCOVER","title":"START HERE","statement":"Black history doesn’t start in 1619. It starts in Africa.","reveal":"Enslavement is a rupture in a longer African history—not the beginning of Black existence.","points":10,"node_ids":["V1-001"],"world":"IDENTITY","source":"Four Hundred Souls — Africa"},{"id":"D002","mode":"DISCOVER","title":"DU BOIS","statement":"You can know yourself—and still feel yourself being measured through somebody else’s eyes.","reveal":"Du Bois called this tension double consciousness.","points":10,"node_ids":["V1-019"],"world":"IDENTITY","source":"Black AF History — Introduction / The Souls of Black Folk"},{"id":"D003","mode":"DISCOVER","title":"ELLA BAKER","statement":"Strong leadership should leave more people capable of leading.","reveal":"Baker favored participatory leadership over a movement dependent on one public figure.","points":10,"node_ids":["V1-034"],"world":"ORGANIZING","source":"Black AF History + Four Hundred Souls — Ella Baker"},{"id":"D004","mode":"DISCOVER","title":"FREEDOM’S JOURNAL","statement":"Owning the platform can be part of owning the story.","reveal":"Black-controlled media gave Black communities a way to define themselves publicly.","points":10,"node_ids":["V1-010"],"world":"CULTURE","source":"Four Hundred Souls — Freedom’s Journal"},{"id":"D005","mode":"DISCOVER","title":"RECONSTRUCTION","statement":"Ending slavery answered one question. Freedom created several more.","reveal":"Citizenship, voting, education, land, labor, and political power still had to be fought over.","points":10,"node_ids":["V1-015"],"world":"POWER","source":"Four Hundred Souls + Black AF History — Reconstruction"},{"id":"D006","mode":"DISCOVER","title":"IDA B. WELLS","statement":"Before accepting the story used to justify violence, check the evidence.","reveal":"Wells used reporting and statistics to challenge the myths used to defend lynching.","points":10,"node_ids":["V1-021"],"world":"POWER","source":"Black AF History — Ida B. Wells"},{"id":"D007","mode":"DISCOVER","title":"ZORA NEALE HURSTON","statement":"Black life did not need to become a protest message before it could become art.","reveal":"Hurston treated vernacular, folklore, humor, and ordinary life as worthy subjects themselves.","points":10,"node_ids":["V1-027"],"world":"CULTURE","source":"Four Hundred Souls — Zora Neale Hurston"},{"id":"D008","mode":"DISCOVER","title":"MALCOLM X","statement":"A struggle for citizenship can also be framed as a struggle for human rights.","reveal":"Malcolm increasingly placed Black freedom inside a global story of self-determination and anticolonial struggle.","points":10,"node_ids":["V1-036"],"world":"FREEDOM","source":"Black AF History + Four Hundred Souls — Malcolm X"}],"starter_sessions":[{"id":"S01","title":"WHO DEFINES THE STORY?","encounters":["D001","D002","E002","D004","E006","E010"],"keep_this":"History changes when you change who gets to define the story.","purpose":"Introduce DISCOVER, multiple choice, and RECALL without exceeding two quiz screens in a row."},{"id":"S02","title":"WHAT DOES FREEDOM REQUIRE?","encounters":["D005","E005","E014","E007","E027","E018"],"keep_this":"Ending a barrier and building freedom are not the same job.","purpose":"Introduce context, strategy comparison, recall, and timeline."},{"id":"S03","title":"HOW DOES POWER MOVE?","encounters":["D006","E004","D003","E014","E034","E039"],"keep_this":"Attention matters. Organization, leverage, and leadership determine what happens next.","purpose":"Introduce evidence, organizing, fair comparison, connection, and SHARE."}],"session_end":{"layout":["+KNOWLEDGE total","ideas strengthened","new connections discovered","KEEP THIS","DONE / KEEP PLAYING"],"rule":"KEEP THIS is one short idea from the session, never a paragraph.","avoid":["accuracy percentage","streak-loss warning","leaderboard pressure","multiple currencies"]}},"links":{"_about":"Editorial wiring between the two authoritative content files. It adds NO historical claims: it only maps existing debates and threads onto existing curriculum node ids so the game can decide when they unlock. Edit freely; run `npm run data` afterwards.","debates":{"D-01":{"sides":[["V1-018"],["V1-019","V1-020"]],"side_labels":["Washington","Du Bois"],"encounters":[]},"D-02":{"sides":[["V1-018"],["V1-021","V1-022"]],"side_labels":["Washington","Wells"],"encounters":["E011"]},"D-03":{"sides":[["V1-034"],["V1-035"]],"side_labels":["Baker","King"],"encounters":["E014"]},"D-04":{"sides":[["V1-035"],["V1-036"]],"side_labels":["King","Malcolm X"],"encounters":["E033"]},"D-05":{"sides":[["V1-032"],["V1-037"]],"side_labels":["Integration","Black Power"],"encounters":["E022"]},"D-06":{"sides":[["V1-027"],["V1-026"]],"side_labels":["Hurston","Protest-art tradition"],"encounters":[]},"D-07":{"sides":[["V1-039"],[]],"side_labels":["Combahee","Male-centered liberation politics"],"encounters":[]}},"threads":{"T-01":[["V1-004"],["V1-025"],["V1-032","V1-015"],["V1-030"],["V1-037"]],"T-02":[["V1-022","V1-021"],["V1-031"],["V1-033"],["V1-038"]],"T-03":[["V1-013"],["V1-021"],["V1-019","V1-020"]],"T-04":[["V1-007"],["V1-014"],["V1-018"],["V1-030"],["V1-034"],["V1-038"]],"T-05":[["V1-012"],["V1-033"],["V1-034"],[],["V1-044"]],"T-06":[["V1-001"],["V1-019"],["V1-026"],["V1-027"],["V1-028"],["V1-040"],["V1-042"]],"T-07":[["V1-015"],["V1-017"],["V1-032"],[],["V1-043"]]},"thread_unlock_steps":3,"_threads_note":"Each thread entry lists, per step of the curriculum's `path`, the node ids that satisfy that step (any one of them). An empty list means the step has no playable node yet (e.g. 'Boynton/context', 'Voting Rights').","boss_min_nodes":{"E040":4},"_boss_note":"E040's design_note says it unlocks after at least four linked nodes have been encountered; this overrides the generic 'all linked nodes' unlock rule for that one encounter.","context":{"CTX-01":["V1-008","V1-015"],"CTX-02":["V1-021","V1-022","V1-018","V1-025"],"CTX-03":["V1-035","V1-036","V1-038","V1-037"],"CTX-04":["V1-017","V1-018","V1-021","V1-025"],"CTX-05":[],"CTX-06":[],"CTX-07":["V1-043"]},"_context_note":"Context cards are linked only to the nodes their curriculum `purpose` text names. CTX-05 and CTX-06 name no playable node yet, so they stay unavailable."},"words":{"_about":"FALLBACK WORDS bank transcribed verbatim (wording, speaker, node links) from docs/black_folk_knowledge_map_words_v1_brief.md, because black_folk_words_quote_bank_v1.json was not supplied. Source citations are intentionally null rather than guessed. Drop the authoritative quote bank into /content as black_folk_words_quote_bank_v1.json and it will be used instead.","provenance":"black_folk_knowledge_map_words_v1_brief.md","quotes":[{"id":"W-01","speaker":"Freedom’s Journal editors","text":"We wish to plead our own cause","node_ids":["V1-010"],"source":null,"year":null},{"id":"W-02","speaker":"Freedom’s Journal editors","text":"Too long have others spoken for us.","node_ids":["V1-010"],"source":null,"year":null},{"id":"W-03","speaker":"Maria Stewart","text":"Sue for your rights and privileges. Know the reason you cannot attain them.","node_ids":["V1-011"],"source":null,"year":null},{"id":"W-04","speaker":"Maria Stewart","text":"possess the spirit of men, bold and enterprising, fearless and undaunted.","node_ids":["V1-011"],"source":null,"year":null},{"id":"W-05","speaker":"Booker T. Washington","text":"Cast down your bucket where you are.","node_ids":["V1-018"],"source":null,"year":null},{"id":"W-06","speaker":"Booker T. Washington","text":"The wisest among my race understand that the agitation of questions of social equality is the extremist folly.","node_ids":["V1-018"],"source":null,"year":null},{"id":"W-07","speaker":"Frederick Douglass","text":"a mightier work than the abolition of slavery","node_ids":["V1-014","V1-015"],"source":null,"year":null},{"id":"W-08","speaker":"Frederick Douglass","text":"Men talk of the Negro problem. There is no Negro problem","node_ids":["V1-014"],"source":null,"year":null},{"id":"W-09","speaker":"Frederick Douglass","text":"shall not brand the Declaration of Independence as a lie.","node_ids":["V1-014"],"source":null,"year":null},{"id":"W-10","speaker":"Frederick Douglass","text":"there is no power on earth which can deny that he has earned the right to citizenship.","node_ids":["V1-014","V1-015"],"source":null,"year":null},{"id":"W-11","speaker":"W.E.B. Du Bois","text":"How does it feel to be a problem?","node_ids":["V1-019"],"source":null,"year":null},{"id":"W-12","speaker":"W.E.B. Du Bois","text":"two souls, two thoughts, two unreconciled strivings","node_ids":["V1-019"],"source":null,"year":null},{"id":"W-13","speaker":"Ida B. Wells","text":"lynching is not invoked to punish crime but color","node_ids":["V1-021"],"source":null,"year":null},{"id":"W-14","speaker":"Ida B. Wells","text":"one had better die fighting against injustice than to die like a dog or rat in a trap.","node_ids":["V1-022"],"source":null,"year":null},{"id":"W-15","speaker":"Ida B. Wells","text":"save our money and leave a town which will neither protect our lives and property","node_ids":["V1-022","V1-025"],"source":null,"year":null},{"id":"W-16","speaker":"Mary McLeod Bethune","text":"But more can be done","node_ids":["V1-030"],"source":null,"year":null},{"id":"W-17","speaker":"Mary Church Terrell","text":"Do you mean to tell me that you are not going to serve me?","node_ids":["V1-023"],"source":null,"year":null},{"id":"W-18","speaker":"James Baldwin","text":"We made the world we are living in and we have to make it over again.","node_ids":["V1-028"],"source":null,"year":null},{"id":"W-19","speaker":"Stokely Carmichael","text":"What we gonna start saying now is Black Power!","node_ids":["V1-037"],"source":null,"year":null},{"id":"W-20","speaker":"Martin Luther King Jr.","text":"the biggest purveyor of violence in the world.","node_ids":["V1-035"],"source":null,"year":null},{"id":"W-21","speaker":"Malcolm X","text":"they would cease to measure others always in terms of their ‘differences in color,’","node_ids":["V1-036"],"source":null,"year":null},{"id":"W-22","speaker":"Rosa Parks","text":"talked and talked of everything I know about the white man’s inhuman treatment of the negro.","node_ids":["V1-033"],"source":null,"year":null},{"id":"W-23","speaker":"Zora Neale Hurston","text":"had been dammed up in me.","node_ids":["V1-027"],"source":null,"year":null}]},"wordsSource":"words_from_brief.json","knowledgeMap":null};
